import React, { useEffect, useState } from "react";
import { getDailyBoxOffice } from "../api/boxofficeApi";
import MovieCard from "../components/MovieCard";

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchBoxOffice = async () => {
      setLoading(true);
      try {
        const today = new Date();
        today.setDate(today.getDate() - 1); // 어제 날짜
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, "0");
        const dd = String(today.getDate()).padStart(2, "0");
        const targetDt = `${yyyy}${mm}${dd}`; // 'yyyymmdd' 포맷

        const result = await getDailyBoxOffice(targetDt);

        // 영화 데이터를 MovieCard 형식에 맞게 가공
        const mappedMovies = result.map((movie, index) => ({
          id: index,
          title: movie.movieNm,
          poster_path: "https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=No+Image", // KOFIC에 포스터 없음
          description: `개봉일: ${movie.openDt}\n누적관객: ${parseInt(movie.audiAcc).toLocaleString()}명\n일일 관객: ${parseInt(movie.audiCnt).toLocaleString()}명\n스크린 수: ${movie.scrnCnt}`,
        }));

        setMovies(mappedMovies);
      } catch (error) {
        console.error("박스오피스 데이터를 불러오는 데 실패했습니다:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchBoxOffice();
  }, []);

  if (loading) return <div>로딩 중...</div>;

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>📊 일별 박스오피스</h1>
      <div style={styles.movieGrid}>
        {movies.map((movie) => (
          <MovieCard key={movie.id} movie={movie} />
        ))}
      </div>
    </div>
  );
}

const styles = {
  container: {
    width: "100%",
    maxWidth: "1200px",
    margin: "0 auto",
    padding: "2rem",
    boxSizing: "border-box",
  },
  title: {
    fontSize: "2.5rem",
    textAlign: "center",
    marginBottom: "3rem",
    fontWeight: "bold",
  },
  movieGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(3, 1fr)",
    columnGap: "2rem",
    rowGap: "3rem",
  },
};

export default HomePage;
